class Solution {
public:
    vector<string> shortestSubstrings(vector<string>& arr) {
        int n = arr.size();
        vector<string> ans;
        for (int i = 0; i < n; ++i) {
            vector<string> subs;
            int L = arr[i].size();
            for (int len = 1; len <= L; ++len) {
                for (int start = 0; start <= L - len; ++start) {
                    subs.push_back(arr[i].substr(start, len));
                }
            }
            sort(subs.begin(), subs.end(), [](const string& a, const string& b) {
                if (a.size() != b.size()) return a.size() < b.size();
                return a < b;
            });
            string found = "";
            for (const string& sub : subs) {
                bool valid = true;
                for (int j = 0; j < n; ++j) {
                    if (j != i && arr[j].find(sub) != string::npos) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    found = sub;
                    break;
                }
            }
            ans.push_back(found);
        }
        return ans;
    }
};

class Solution {
    public String[] shortestSubstrings(String[] arr) {
        int n = arr.length;
        String[] ans = new String[n];
        for (int i = 0; i < n; i++) {
            List<String> subs = new ArrayList<>();
            int L = arr[i].length();
            for (int len = 1; len <= L; len++) {
                for (int start = 0; start <= L - len; start++) {
                    subs.add(arr[i].substring(start, start + len));
                }
            }
            subs.sort((a, b) -> {
                if (a.length() != b.length()) return Integer.compare(a.length(), b.length());
                return a.compareTo(b);
            });
            String found = "";
            for (String sub : subs) {
                boolean valid = true;
                for (int j = 0; j < n; j++) {
                    if (j != i && arr[j].contains(sub)) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    found = sub;
                    break;
                }
            }
            ans[i] = found;
        }
        return ans;
    }
}

var shortestSubstrings = function(arr) {
    const ans = [];
    const n = arr.length;
    for (let i = 0; i < n; ++i) {
        const word = arr[i];
        const subs = new Set();
        const L = word.length;
        for (let len = 1; len <= L; ++len) {
            for (let start = 0; start <= L - len; ++start) {
                subs.add(word.substring(start, start + len));
            }
        }
        const sorted = Array.from(subs).sort((a, b) => {
            if (a.length !== b.length) return a.length - b.length;
            return a.localeCompare(b);
        });
        let found = '';
        for (const sub of sorted) {
            let valid = true;
            for (let j = 0; j < n; ++j) {
                if (j !== i && arr[j].includes(sub)) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                found = sub;
                break;
            }
        }
        ans.push(found);
    }
    return ans;
};
